9: export class AuthGuard implements CanActivate {
10:   constructor(
11:     private popUpManager: PopUpManager,
12:     private translate: TranslateService,
13:   ) {}
14: 
15:   canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
16:     const menuPermisos = parseMenuPermissions(localStorage.getItem('menu'));
17:     const fullUrl = window.location.href;
18:     const url = new URL(fullUrl);
19:     const path = url.pathname;
20:     const params = route.params;
21: 
22:     if (menuPermisos != null && checkUrlExists(menuPermisos, path, params)) {
23:       return true;
24:     }
25: 
26:     this.translate.get('ERROR.rol_insuficiente_titulo').subscribe((message: string) => {
27:       this.popUpManager.showErrorAlert(message);
28:     });
29:     return false;
30:   }
31: 
32:   canActivateChild(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
33:     return this.canActivate(route, state);
34:   }
35: }
36: 
37: function parseMenuPermissions(menuInfo: string | null): any[] | null {
38:   if (!menuInfo) {
39:     return null;
40:   }
41: 
42:   try {
43:     return JSON.parse(atob(menuInfo));
44:   } catch {
45:     return null;
46:   }
47: }
48: 
49: function checkUrlExists(menuItems: any[], targetUrl: string, params: any): boolean {
50:   return menuItems.some((item: any) => {
51:     if (item.Url === targetUrl && checkParams(item.Params, params)) {
52:       return true;
53:     }
54: 
55:     if (item.Opciones && item.Opciones.length > 0) {
56:       return checkUrlExists(item.Opciones, targetUrl, params);
57:     }
58: 
59:     return false;
60:   });
61: }
62: 
63: function checkParams(expectedParams: any, actualParams: any): boolean {
64:   if (!expectedParams) {
65:     return true;
66:   }
67: 
68:   for (const key in expectedParams) {
69:     if (expectedParams[key] !== actualParams[key]) {
70:       return false;
71:     }
72:   }
73: 
74:   return true;
75: }

